const I18N_STR = Object.fromEntries(Object.entries(I18N_RAW).map(([k, [zh, en]]) => [k, { zh, en }]));

function trf(key, fallback, vars) {
  const e = I18N_STR[key];
  let s = e && e[I18N_LANG] != null ? e[I18N_LANG] : fallback != null ? fallback : e && e.en != null ? e.en : key;
  if (vars) s = String(s).replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  return s;
}
function tr(key, vars) { return trf(key, null, vars); }
function badgeHTML(kind) { return `<span class="badge ${kind}">${tr('badge.' + kind)}</span>`; }

function applyI18n(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = tr(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-html]').forEach((el) => { el.innerHTML = tr(el.dataset.i18nHtml); });
  document.documentElement.lang = I18N_LANG === 'zh' ? 'zh-Hant-TW' : 'en';
  // keep a non-default language when moving between pages
  if (I18N_LANG !== I18N_DEFAULT) {
    root.querySelectorAll('header#top a[href]').forEach((a) => {
      const h = a.getAttribute('href'); if (/^https?:/.test(h)) return;
      a.setAttribute('href', h + (h.includes('?') ? '&' : '?') + 'lang=' + I18N_LANG);
    });
  }
}
applyI18n();
